{
  "name": "commerce",
  "compatibilityLevel": 1702,
  "model": {
    "tables": [
      {
        "name": "orders",
        "columns": [
          {
            "name": "id",
            "sourceColumn": "id",
            "dataType": "decimal",
            "isKey": true
          },
          {
            "name": "customer_id",
            "sourceColumn": "customer_id",
            "dataType": "decimal"
          },
          {
            "name": "ordered_at",
            "sourceColumn": "ordered_at",
            "dataType": "dateTime"
          },
          {
            "name": "amount",
            "sourceColumn": "amount",
            "dataType": "decimal"
          }
        ],
        "description": "One row per order",
        "partitions": [
          {
            "name": "orders",
            "mode": "directLake",
            "source": {
              "type": "entity",
              "entityName": "ORDERS",
              "schemaName": "PUBLIC",
              "expressionSource": "DatabaseQuery"
            }
          }
        ],
        "measures": [
          {
            "name": "revenue",
            "expression": "SUM('orders'[amount])",
            "description": "Total order revenue",
            "annotations": [
              {
                "name": "OssieExpressionDialect",
                "value": "ANSI_SQL"
              },
              {
                "name": "OssieExpression",
                "value": "SUM(orders.amount)"
              }
            ]
          },
          {
            "name": "order_count",
            "expression": "DISTINCTCOUNTNOBLANK('orders'[id])",
            "annotations": [
              {
                "name": "OssieExpressionDialect",
                "value": "ANSI_SQL"
              },
              {
                "name": "OssieExpression",
                "value": "COUNT(DISTINCT orders.id)"
              }
            ]
          }
        ]
      },
      {
        "name": "customers",
        "columns": [
          {
            "name": "id",
            "sourceColumn": "id",
            "dataType": "decimal",
            "isKey": true
          },
          {
            "name": "name",
            "sourceColumn": "name",
            "dataType": "string"
          },
          {
            "name": "segment",
            "sourceColumn": "segment",
            "dataType": "string"
          }
        ],
        "description": "Customer attributes",
        "partitions": [
          {
            "name": "customers",
            "mode": "directLake",
            "source": {
              "type": "entity",
              "entityName": "CUSTOMERS",
              "schemaName": "PUBLIC",
              "expressionSource": "DatabaseQuery"
            }
          }
        ]
      }
    ],
    "expressions": [
      {
        "name": "DatabaseQuery",
        "kind": "m",
        "expression": [
          "let",
          "    Source = AzureStorage.DataLake(\"https://onelake.dfs.fabric.microsoft.com/00000000-0000-0000-0000-000000000000/00000000-0000-0000-0000-000000000000\")",
          "in",
          "    Source"
        ]
      }
    ],
    "description": "Orders and customer revenue",
    "relationships": [
      {
        "name": "orders_to_customers",
        "fromTable": "orders",
        "fromColumn": "customer_id",
        "toTable": "customers",
        "toColumn": "id"
      }
    ],
    "culture": "en-US"
  }
}
